INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('И1', 'Идентификация', 'Регистрационные данные', 'ИНН, ОГРН, КПП; полное и краткое наименование; организационно-правовая форма; дата регистрации; юридический адрес; статус (действует / реорганизация / ликвидация); руководитель', 'Однозначно связывает новость или запись в реестре с компанией; смена руководителя или статуса — значимое событие');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('И2', 'Идентификация', 'Собственники и группа компаний', 'Учредители и доли; конечные бенефициары; дочерние и зависимые общества; аффилированные лица; история смены владельцев', 'Новости о «дочках», материнской компании и владельцах; санкционный риск через бенефициаров; смена контроля');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('И3', 'Идентификация', 'Ценные бумаги и кредитные рейтинги', 'Тикеры акций; ISIN и параметры облигаций (объём, купон, погашение, оферты); уровень листинга; кредитные рейтинги и прогнозы по ним', 'Котировки, спреды и рейтинговые действия — рыночные сигналы о компании и её аналогах');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('И4', 'Идентификация', 'Бренды, товарные знаки, домены', 'Зарегистрированные товарные знаки и классы МКТУ; коммерческие обозначения; сайты и домены', 'Распознавание компании в текстах (в новостях её чаще называют брендом); мониторинг упоминаний бренда');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('И5', 'Идентификация', 'Особые статусы', 'Категория МСП; аккредитованная ИТ-компания; резидент ОЭЗ или Сколково; системообразующая организация; получатель господдержки', 'Определяет, какие льготы, меры поддержки и требования касаются компании');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('И6', 'Идентификация', 'Санкционный статус', 'Наличие компании, бенефициаров, дочерних обществ и банков-партнёров в санкционных списках США, ЕС, Великобритании; перечни Росфинмониторинга', 'Риск блокировки платежей и разрыва контрактов; каждый новый пакет санкций проверяется по профилю автоматически');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('И7', 'Идентификация', 'Правовой статус и надёжность', 'Арбитражные дела (истец/ответчик, суммы); дела в судах общей юрисдикции; исполнительные производства; сообщения о банкротстве; включение в РНП; налоговая задолженность; индексы риска', 'Ранние сигналы о проблемах у компании и её контрагентов');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Б1', 'Бизнес', 'Отрасль и виды деятельности', 'ОКВЭД основной и дополнительные; отрасль и подотрасль; коды продукции ОКПД2; лицензии на виды деятельности', 'Определяет отраслевые обзоры, регуляторику и сырьевые драйверы, релевантные компании');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Б2', 'Бизнес', 'Финансовые результаты', 'Выручка, себестоимость, валовая и операционная маржа, чистая прибыль, EBITDA, операционный денежный поток; динамика за 3–5 лет', 'Задаёт порог существенности и базу для расчёта эффекта события в рублях');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Б3', 'Бизнес', 'Долг и чувствительность к ставке', 'Кредиты и займы (кратко- и долгосрочные); облигации в обращении; лизинг; залоги; долг/EBITDA; доля плавающих ставок; текущая и прогнозная ключевая ставка', 'Пересчёт решений ЦБ и прогнозов ставки в процентные расходы; окна для рефинансирования и размещения');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Б4', 'Бизнес', 'Налоги и обязательные платежи', 'Уплаченные налоги и взносы; налоговый режим; недоимки и штрафы; налоговая нагрузка в сравнении с отраслью; изменения налогового законодательства', 'Оценка влияния налоговых изменений (НДС, налог на прибыль, взносы) на компанию');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Б5', 'Бизнес', 'Персонал', 'Среднесписочная численность; ФОТ; открытые вакансии и предлагаемые зарплаты; ключевые и дефицитные профессии', 'Сравнение с рынком труда региона; оценка давления на ФОТ и кадровых рисков');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Б6', 'Бизнес', 'Продукция и производство', 'Номенклатура продукции; подтверждение российского производства и баллы локализации; сертификаты и декларации соответствия; маркировка; опасные производственные объекты', 'Изменения техрегламентов, требований локализации и господдержки касаются конкретных продуктов и площадок');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Б7', 'Бизнес', 'Технологии и ИТ', 'Патенты, полезные модели, программы для ЭВМ; продукты в реестре российского ПО; гранты на НИОКР; используемые ИТ-системы', 'Технологическая позиция относительно конкурентов; влияние импортозамещения ПО и ИТ-льгот');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Б8', 'Бизнес', 'Клиенты и каналы сбыта', 'Ключевые покупатели (ИНН); госконтракты и коммерческие тендеры; доля госзаказа; каналы: опт, розница, маркетплейсы, экспорт; дебиторская задолженность', 'Ранние сигналы о спросе и платёжеспособности покупателей; новые тендеры');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Б9', 'Бизнес', 'Поставщики и сырьё', 'Ключевые поставщики (ИНН); план закупок; критичное сырьё и его цены; импортная доля; запасы и кредиторская задолженность; стоимость доставки', 'Новость о цене, дефиците или проблемах поставщика → оценка влияния на себестоимость и сроки');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Б10', 'Бизнес', 'Конкуренты и доля рынка', '5–10 конкурентов (ИНН); их выручка, маржа и динамика; тендеры; сделки; доля рынка; оценки аналитиков по публичным аналогам', 'Сравнение с конкурентами и реакция на их действия');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Б11', 'Бизнес', 'Спрос в отрасли', 'Индикаторы деловой активности и спроса в отрасли компании и её клиентов: PMI, бизнес-климат, потребительские расходы, поисковый спрос, промпроизводство, отраслевые рынки', 'Опережающие сигналы изменения продаж');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Б12', 'Бизнес', 'Репутация и медиаприсутствие', 'Упоминания в СМИ, Telegram и соцсетях; тональность; рейтинги и отзывы; позиции на маркетплейсах; брендовый поисковый спрос; рекламная активность; нарушения в рекламе', 'Реакция на негатив; восприятие бренда относительно конкурентов');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Г1', 'География', 'Адреса и площадки', 'Юридический адрес; филиалы и представительства; производственные площадки, склады, объекты недвижимости; энергоснабжение площадок', 'Локальные события (ЧС, отключения, ограничения, тарифы) привязываются к площадкам компании');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Г2', 'География', 'Регионы продаж и закупок', 'Регионы заказчиков и поставщиков; доля регионов в выручке; спрос и экономическая ситуация в регионах присутствия', 'Региональные новости, меры поддержки и спрос отбираются по регионам компании');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Г3', 'География', 'ВЭД: страны и валюты', 'Страны экспорта и импорта; валюты контрактов; иностранные контрагенты; пошлины и требования; торговые потоки по товарным позициям', 'Курсовые и санкционные события, изменения пошлин и платёжных маршрутов по странам компании');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('Г4', 'География', 'Логистика', 'Маршруты и виды транспорта; порты и погранпереходы; ставки фрахта и автоперевозок; ж/д погрузка; движение судов; топливо на маршрутах', 'События на маршрутах компании: ограничения, задержки, рост стоимости доставки');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('С1', 'Стратегия', 'Цели и инвестпрограмма', 'Опубликованная стратегия; инвестпрограмма и капвложения; решения совета директоров; дивидендная политика; крупные проекты', 'Ранжирование возможностей и рисков под цели компании');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('С2', 'Стратегия', 'Господдержка и регулирование', 'Полученные субсидии и льготные займы; участие в госпрограммах; законопроекты и нормативные акты, затрагивающие отрасль; решения ФАС', 'Своевременная реакция на изменения правил и новые меры поддержки');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('С3', 'Стратегия', 'M&A и корпоративные события', 'Сделки покупки и продажи, смена контроля, IPO/SPO, реорганизации — у компании, конкурентов и партнёров', 'Изменение конкурентного поля и окна для сделок');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('С4', 'Стратегия', 'Макросценарий', 'Базовый сценарий для планирования: ВВП, инфляция, ключевая ставка, курс рубля, бюджет, мировая конъюнктура, санкционная повестка', 'Единая макро-рамка, в которой оцениваются все остальные события');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('С5', 'Стратегия', 'Рыночные возможности', 'Новые рынки и ниши; тендеры и торги; экспортные направления; программы поддержки экспорта; идеи для свободной ликвидности', 'Проактивные предложения: где компания может вырасти');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('О1', 'Отношения с банком', 'Расчёты и денежный поток', 'Обороты и остатки по счетам (включая другие банки через мультибанкинг); сезонность; граф платежей с контрагентами', 'Расчёт эффекта событий в рублях и проверка ликвидности');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('О2', 'Отношения с банком', 'Кредиты и ковенанты', 'Кредитные договоры и лимиты; ставки (фиксированная / плавающая); графики погашения; ковенанты; гарантии', 'Предупреждения о риске нарушения ковенантов; предложения по рефинансированию');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('О3', 'Отношения с банком', 'Валютные операции и хеджирование', 'Валютные контракты (УНК); ведомость банковского контроля; конверсии; открытые хеджи (форварды, опционы)', 'Действие в конце инсайта: зафиксировать курс, сменить маршрут платежа');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('О4', 'Отношения с банком', 'Размещение средств', 'Депозиты; ценные бумаги; брокерский счёт; стратегия управления ликвидностью', 'Предложения по размещению свободных средств при изменении ставок');
INSERT INTO profile_elements (code, block, name, description, purpose) VALUES ('О5', 'Отношения с банком', 'Канал и пользователи', 'Персональный менеджер; пользователи интернет-банка и их права (роли, право подписи); подключение Альфа-Босс; доступные компании продукты', 'Кому из директоров и в какой канал доставлять инсайт; какое действие предложить');
